_RockCommerce.prototype.addProductInfo=function(info){this.productinfos=this.productinfos||[];this.productinfos.push(info)};document.addEventListener("alpine:init",()=>{Alpine.data("rcproductinfo",()=>({count:0,min:1,init(){this.setMin();this.setCount();this.initUpdateUrl();RockCommerce.addProductInfo(this)},decrement(){if(this.count>this.min)this.count--;else this.count=this.min},increment(){if(this.count<this.min)this.count=this.min;else this.count++},initUpdateUrl(){this.updateUrl=!!this.$el.getAttribute("data-rc-updateurl")},setCount(count){if(!count){let el=this.$el.querySelector("input[x-model=count]");el.addEventListener("focus",el.select);if(!el)return;count=el.value}
if(!count)return;this.count=count},setMin(){this.min=1;let el=this.$el.querySelector("input[x-model=count]");if(!el)return;this.min=el.getAttribute("min")||this.min},}))})